    function updatePracticeProgress(){
      const done=state.practiceSet.filter((q,i)=>practiceParts(q).every((_,j)=>String(state.practiceDrafts[i]?.[j]||"").trim())).length;
      const bar=document.querySelector(".practice-progress");if(!bar)return;
      bar.setAttribute("aria-valuenow",String(done));bar.querySelectorAll(".practice-progress-segment").forEach((segment,i)=>segment.classList.toggle("is-complete",i<done));
      const value=$("practiceProgressValue"),count=$("practiceProgressCount");if(value)value.textContent=`${done} / 5`;if(count)count.textContent=state.practiceSubmitted?`${done} of 5 questions completed`:done===5?"Ready to check":`${5-done} questions left`;
    }
    function submitPracticeAnswers(){
      if(state.practiceSubmitted){route("practiceResults");return}
      for(let i=0;i<state.practiceSet.length;i++)for(let j=0;j<practiceParts(state.practiceSet[i]).length;j++){
        const part=practiceParts(state.practiceSet[i])[j],input=$("practiceAnswerInput"+i+"_"+j),grade=AppMarking.grade(state.practiceDrafts[i]?.[j],part.answers);
        if(grade.status==="unreadable"){state.practiceIndex=i;render();AppUI.inputError($("practiceAnswerInput"+i+"_"+j),"I could not read this answer. Check the brackets or use x^2 and sqrt(x). It has not been marked wrong.");return;}
      }
      state.practiceAnswers=state.practiceSet.map((q,i)=>({parts:practiceParts(q).map((part,j)=>{
        const input=String(state.practiceDrafts[i]?.[j]||"").trim(),answered=input.length>0,correct=answered&&AppMarking.grade(input,part.answers).correct,topic=part.subtopic;
        if(answered){
          const stats=state.practiceTopicStats[topic]||(state.practiceTopicStats[topic]={attempts:0,correct:0});
          state.attempts[topic]=Number(state.attempts[topic]||0)+1;stats.attempts=Number(stats.attempts||0)+1;
          if(correct)stats.correct=Number(stats.correct||0)+1;
          if(window.HahaMana)HahaMana.answer("maths","practice:"+q.id+":"+j,correct,(state.practiceHints||[]).includes(q.id));
          recordPractice(correct);if(state.firstTry[topic]==null)state.firstTry[topic]=correct;
          if(correct&&!state.complete[topic]){state.complete[topic]=true;if(!state.awarded[topic]){state.awarded[topic]=true}}
        }
        return{input,answered,correct,marks:part.marks,worked:part.worked,label:part.label,answers:part.answers,prompt:part.prompt};
      })}));
      masteryStore.recordMany(state.practiceSet.flatMap((q,i)=>practiceParts(q).map((_,j)=>{const a=state.practiceAnswers[i].parts[j];return masteryEvent('practice:'+q.id+':'+j,!a.answered?'skip':a.correct?'correct':'incorrect',(state.practiceHints||[]).includes(q.id),state.practiceSessionId+':'+i+':'+j);})));
      state.practiceSubmitted=true;
      if(window.HahaMana)HahaMana.completeSet("maths",state.practiceSet.length>0&&state.practiceSet.every((q,i)=>practiceParts(q).every((_,j)=>String(state.practiceDrafts[i]?.[j]||"").trim().length>0)));
      save();route("practiceResults");
    }
    // Let a short tactile reaction finish before the existing lesson action runs.
    const chessActivationBypass=new WeakSet();
    let chessActivationPending=false;
    document.addEventListener("click",async event=>{
      const button=event.target.closest(".lesson-trail .lesson-node");
      if(!button||chessActivationBypass.has(button))return;
      const sculpture=button.querySelector(".chess-sculpture");
      if(!sculpture||!sculpture.animate||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
      event.preventDefault();event.stopImmediatePropagation();
      if(chessActivationPending)return;
      chessActivationPending=true;
      button.classList.add("chess-animating");
      const reaction=sculpture.animate([
        {transform:"translateY(0) scale(1) rotate(0deg)",offset:0},
        {transform:"translateY(5px) scale(1.12,.83) rotate(0deg)",offset:.2},
        {transform:"translateY(-15px) scale(.94,1.08) rotate(-7deg)",offset:.5},
        {transform:"translateY(-5px) scale(1.04,.97) rotate(5deg)",offset:.75},
        {transform:"translateY(0) scale(1) rotate(0deg)",offset:1}
      ],{duration:420,easing:"ease-in-out"});
      try{await reaction.finished;}catch{/* A cancelled reaction still opens the lesson. */}
      finally{chessActivationPending=false;button.classList.remove("chess-animating");}
      if(!button.isConnected)return;
      chessActivationBypass.add(button);
      try{button.click();}finally{chessActivationBypass.delete(button);}
    },true);
